<?php
namespace qqworld_collector\module\cloud_storage; use qqworld_collector\module\cloudStorage2; class niupic extends cloudStorage2 { var $exclude_domain = 'niupic.com/'; public function init() { $this->silent_scanning = $this->options->cloud_storage_niupic_silent_scanning; $this->delete_attachment_after_synced = $this->options->cloud_storage_joinmode_enabled ? 0 : $this->options->cloud_storage_niupic_delete_attachment_after_synced; } public function upload($destination_path, $source_path) { if (!file_exists($source_path) || !filesize($source_path)) return false; $name = basename($source_path); preg_match('/(.*?)\\.[A-Za-z0-9]+/', $name,$m); $name=$m[0]; $type = mime_content_type($source_path); $bits = file_get_contents($source_path); $target_url = 'https://niupic.com/api/upload'; $data = array(); $mimeBoundary = '----WebKitFormBoundary' . uniqid(); array_push($data, '--' . $mimeBoundary); $mimeType = empty($type) ? 'application/octet-stream' : $type; array_push($data, "Content-Disposition: form-data; name=\"file\"; filename=\"$name\""); array_push($data, "Content-Type: $mimeType"); array_push($data, ''); array_push($data, $bits); array_push($data, '--' . $mimeBoundary . "--"); $post_data = implode("\r\n", $data); $length = strlen($post_data); $headers = array(); array_push($headers, "Accept: application/json, text/javascript, */*; q=0.01"); array_push($headers, "Accept-Encoding: gzip, deflate"); array_push($headers, "Accept-Language: zh-CN,zh;q=0.9,en;q=0.8,zh-TW;q=0.7,en-US;q=0.6"); array_push($headers, "Connection: keep-alive"); array_push($headers, "Content-Length: {$length}"); array_push($headers, "Content-Type: multipart/form-data; boundary={$mimeBoundary}"); array_push($headers, "Host: niupic.com"); array_push($headers, "Origin: https://niupic.com"); array_push($headers, "Referer: https://niupic.com/"); array_push($headers, "User-Agent: {$this->user_agent}"); array_push($headers, "X-Requested-With: XMLHttpRequest"); $ch = curl_init(); curl_setopt($ch, CURLOPT_URL, $target_url); curl_setopt($ch, CURLOPT_HTTPHEADER, $headers); curl_setopt($ch, CURLOPT_USERAGENT, $this->user_agent); curl_setopt($ch, CURLOPT_POST, 1); curl_setopt($ch, CURLOPT_POSTFIELDS, $post_data); curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1); curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false); curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, false); curl_setopt($ch, CURLOPT_REFERER, 'https://niupic.com/'); $result = curl_exec($ch); curl_close($ch); $result = gzdecode($result); $result = json_decode($result, true); if (isset($result['status']) && $result['status'] = 'success') { return $result['data']; } else { do_action( 'qqworld-collector-log', $this->log_id, 'niupic failed: ', print_r($result, true) ); } return false; } } ?>